insert into public.species (id, cat, "order", name, sci, region, zones, code, size, habitat, depth, speed, diet, rarity, blurb) values
('nodriza', 'tiburon', 'Orectolobiformes', 'Tiburón nodriza', 'Ginglymostoma cirratum', 'Global', ARRAY['caribe'], 'TBR-01', '3 m', 'Fondos arenosos y cuevas', '1–12 m', 'Lenta', 'Moluscos y peces pequeños', 2, 'Habitual en acuarios y arrecifes tropicales. Pasa el día inmóvil en el fondo, a menudo bajo salientes rocosos, y caza de noche por succión.'),
('cebra', 'tiburon', 'Orectolobiformes', 'Tiburón cebra', 'Stegostoma tigrinum', 'Global', ARRAY['indopacifico'], 'TBR-02', '2.5 m', 'Arrecifes de coral', '5–30 m', 'Lenta', 'Moluscos y crustáceos', 3, 'De joven rayado, de adulto con manchas leopardo. Muy presente en acuarios por su carácter tranquilo y su forma de nadar ondulante.'),
('ballena', 'tiburon', 'Orectolobiformes', 'Tiburón ballena', 'Rhincodon typus', 'Global', ARRAY['global'], 'TBR-03', '12 m', 'Aguas abiertas tropicales', '0–200 m', '5 km/h', 'Filtrador de plancton', 5, 'El pez más grande del mundo. Filtra plancton y es completamente inofensivo. Algunos grandes acuarios lo mantienen; en libertad se avista en agregaciones estacionales.'),
('wobbegong', 'tiburon', 'Orectolobiformes', 'Tiburón alfombra ornamentado', 'Orectolobus ornatus', 'Global', ARRAY['indopacifico'], 'TBR-04', '1.2 m', 'Arrecifes rocosos', '5–30 m', 'Muy lenta', 'Peces y crustáceos', 4, 'Camuflado entre rocas y coral gracias a los flecos de piel de su cabeza. Permanece inmóvil en el fondo esperando a sus presas.'),
('charretera', 'tiburon', 'Orectolobiformes', 'Tiburón charretera', 'Hemiscyllium ocellatum', 'Global', ARRAY['indopacifico'], 'TBR-05', '0.9 m', 'Arrecifes someros', '1–5 m', 'Lenta', 'Invertebrados bentónicos', 4, 'Capaz de "caminar" sobre sus aletas por el fondo de los arrecifes someros. Muy popular en acuarios por su tamaño reducido.'),
('puntablanca', 'tiburon', 'Carcharhiniformes', 'Tiburón punta blanca de arrecife', 'Triaenodon obesus', 'Global', ARRAY['indopacifico'], 'TBR-06', '1.6 m', 'Arrecifes de coral', '1–40 m', 'Moderada', 'Peces y cefalópodos', 2, 'Muy común en arrecifes indopacíficos. De hábitos nocturnos, de día suele verse descansando inmóvil en cuevas o bajo salientes.'),
('puntanegra', 'tiburon', 'Carcharhiniformes', 'Tiburón punta negra de arrecife', 'Carcharhinus melanopterus', 'Global', ARRAY['indopacifico'], 'TBR-07', '1.6 m', 'Lagunas de arrecife', '0–20 m', 'Moderada', 'Peces pequeños', 2, 'Habitual en aguas someras de arrecife, incluso en zonas de un metro de profundidad. Fácil de identificar por las puntas negras de sus aletas.'),
('pintarroja', 'tiburon', 'Carcharhiniformes', 'Pintarroja', 'Scyliorhinus canicula', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-08', '0.6 m', 'Fondos de arena y roca', '5–100 m', 'Lenta', 'Crustáceos y moluscos', 2, 'El tiburón más común en fondos de arena y roca del Mediterráneo y costa atlántica española. Pequeño, moteado, y de hábitos nocturnos.'),
('cazon', 'tiburon', 'Carcharhiniformes', 'Cazón', 'Mustelus mustelus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-09', '1.5 m', 'Fondos arenosos costeros', '5–50 m', 'Moderada', 'Crustáceos', 2, 'Tiburón gris de tamaño medio frecuente en fondos arenosos del litoral español. Se alimenta principalmente de crustáceos.'),
('martillo', 'tiburon', 'Carcharhiniformes', 'Tiburón martillo común', 'Sphyrna lewini', 'Global', ARRAY['global'], 'TBR-10', '3.5 m', 'Montes submarinos', '0–275 m', 'Rápida', 'Peces y cefalópodos', 4, 'Reconocible por su cabeza en forma de martillo. Suele verse en cardúmenes cerca de montes submarinos y en puntos de buceo tropicales.'),
('martilloliso', 'tiburon', 'Carcharhiniformes', 'Tiburón martillo liso', 'Sphyrna zygaena', 'Global', ARRAY['mediterraneo','cantabrico','canarias','caribe','indopacifico'], 'TBR-32', '3.5 m', 'Aguas costeras y pelágicas templadas', '0–200 m', 'Rápida', 'Peces, calamares y otros tiburones', 4, 'Se diferencia de otras especies de tiburón martillo por el borde frontal de su cabeza, liso y sin muescas centrales. Tolera aguas más frías que sus parientes, por lo que se ve en zonas templadas además de tropicales.'),
('limon', 'tiburon', 'Carcharhiniformes', 'Tiburón limón', 'Negaprion brevirostris', 'Global', ARRAY['caribe'], 'TBR-11', '3 m', 'Manglares y aguas costeras', '1–90 m', 'Moderada', 'Peces óseos', 3, 'De color amarillo-grisáceo, frecuenta aguas costeras someras y manglares. Habitual en centros de buceo del Caribe y en acuarios.'),
('tope', 'tiburon', 'Carcharhiniformes', 'Tiburón tope (alitán)', 'Galeorhinus galeus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-12', '1.9 m', 'Fondos costeros', '2–470 m', 'Moderada', 'Peces y cefalópodos', 4, 'Tiburón esbelto de fondos costeros mediterráneos, históricamente pescado por su carne y aletas. Suele desplazarse en pequeños grupos.'),
('toro', 'tiburon', 'Carcharhiniformes', 'Tiburón toro', 'Carcharhinus leucas', 'Global', ARRAY['global','caribe'], 'TBR-13', '3.4 m', 'Estuarios y ríos', '1–150 m', 'Moderada', 'Peces, rayas y crustáceos', 4, 'Tolera aguas dulces y remonta ríos. Uno de los tiburones costeros más adaptables, presente en estuarios y aguas someras de todo el mundo.'),
('sedoso', 'tiburon', 'Carcharhiniformes', 'Tiburón sedoso', 'Carcharhinus falciformis', 'Global', ARRAY['global'], 'TBR-14', '3.3 m', 'Arrecifes de pared', '0–500 m', 'Rápida', 'Peces pelágicos', 4, 'Llamado así por la textura lisa de su piel. Habitual cerca de arrecifes de pared y montes submarinos en aguas tropicales.'),
('azul', 'tiburon', 'Carcharhiniformes', 'Tintorera (tiburón azul)', 'Prionace glauca', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-15', '3.8 m', 'Aguas pelágicas', '0–350 m', 'Rápida', 'Peces y calamares', 3, 'Esbelto y de color azul intenso, es el tiburón pelágico más avistado en salidas de buceo en jaula frente a las costas españolas.'),
('tigredearena', 'tiburon', 'Lamniformes', 'Tiburón tigre de arena', 'Carcharias taurus', 'Global', ARRAY['global'], 'TBR-16', '3.2 m', 'Cuevas y pecios', '5–25 m', 'Lenta', 'Peces óseos', 3, 'Aspecto fiero pero carácter tranquilo; uno de los tiburones más exhibidos en grandes acuarios de todo el mundo.'),
('peregrino', 'tiburon', 'Lamniformes', 'Tiburón peregrino', 'Cetorhinus maximus', 'Global', ARRAY['global','cantabrico'], 'TBR-17', '9 m', 'Aguas templadas costeras', '0–200 m', '3 km/h', 'Filtrador de plancton', 5, 'Segundo pez más grande del mundo, filtrador de plancton. Se avista estacionalmente en la costa cantábrica y otras aguas templadas.'),
('blanco', 'tiburon', 'Lamniformes', 'Tiburón blanco', 'Carcharodon carcharias', 'Global', ARRAY['global','mediterraneo'], 'TBR-18', '5.5 m', 'Aguas costeras templadas', '0–250 m', 'Hasta 25 km/h', 'Focas y peces grandes', 5, 'El mayor depredador entre los tiburones. Icónico de las expediciones de buceo en jaula en aguas frías de varios continentes.'),
('marrajo', 'tiburon', 'Lamniformes', 'Marrajo dientuso', 'Isurus oxyrinchus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-19', '3.5 m', 'Aguas pelágicas', '0–500 m', 'Hasta 70 km/h', 'Peces rápidos y calamares', 5, 'El tiburón más rápido, capaz de saltar fuera del agua. Presente en aguas pelágicas mediterráneas, aunque cada vez más escaso.'),
('angelote', 'tiburon', 'Squatiniformes', 'Angelote', 'Squatina squatina', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-20', '2 m', 'Fondos arenosos', '5–150 m', 'Muy lenta', 'Peces y crustáceos', 5, 'Tiburón plano que se camufla enterrado en la arena. En peligro crítico de extinción; Canarias es uno de sus últimos refugios importantes.'),
('cornudo', 'tiburon', 'Heterodontiformes', 'Tiburón de Port Jackson', 'Heterodontus portusjacksoni', 'Global', ARRAY['indopacifico'], 'TBR-21', '1.6 m', 'Fondos rocosos', '0–275 m', 'Lenta', 'Erizos y moluscos', 3, 'Reconocible por las crestas óseas sobre sus ojos y sus dientes traseros aplanados para triturar erizos y moluscos. Muy expuesto en acuarios.'),
('cuernocalifornia', 'tiburon', 'Heterodontiformes', 'Tiburón cuerno de California', 'Heterodontus francisci', 'Global', ARRAY['global'], 'TBR-22', '1.2 m', 'Fondos rocosos y algas', '2–150 m', 'Lenta', 'Erizos y crustáceos', 4, 'Pequeño y de hábitos nocturnos, descansa de día entre rocas y algas en aguas someras del Pacífico oriental.'),
('sietebranquias', 'tiburon', 'Hexanchiformes', 'Tiburón de siete branquias', 'Notorynchus cepedianus', 'Global', ARRAY['global','cantabrico'], 'TBR-23', '3 m', 'Bahías costeras', '0–136 m', 'Moderada', 'Peces y otros tiburones', 5, 'Uno de los pocos tiburones con siete hendiduras branquiales en lugar de cinco. Frecuenta bahías costeras poco profundas para alimentarse.'),
('quelvacho', 'tiburon', 'Hexanchiformes', 'Quelvacho (tiburón anguila)', 'Hexanchus griseus', 'Global', ARRAY['global','mediterraneo','cantabrico'], 'TBR-24', '4.8 m', 'Fondos profundos', '90–1100 m', 'Lenta', 'Peces y calamares', 5, 'Uno de los tiburones vivos más primitivos, de hábitos profundos aunque ocasionalmente asciende a aguas someras de noche.'),
('mielga', 'tiburon', 'Squaliformes', 'Mielga (tollo espinoso)', 'Squalus acanthias', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-25', '1.2 m', 'Aguas costeras frías', '10–200 m', 'Moderada', 'Peces pequeños', 3, 'Pequeño tiburón gregario con una espina venenosa delante de cada aleta dorsal. Habitual en aguas costeras frías del Atlántico y Mediterráneo.'),
('centrina', 'tiburon', 'Squaliformes', 'Centrina', 'Oxynotus centrina', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'TBR-26', '1.5 m', 'Plataforma continental', '50–650 m', 'Lenta', 'Invertebrados bentónicos', 5, 'Cuerpo alto y comprimido con grandes aletas dorsales triangulares. Vive en fondos de la plataforma continental mediterránea.'),
('sierratiburon', 'tiburon', 'Pristiophoriformes', 'Tiburón sierra', 'Pristiophorus cirratus', 'Global', ARRAY['indopacifico'], 'TBR-27', '1.4 m', 'Fondos arenosos profundos', '40–300 m', 'Lenta', 'Peces y crustáceos', 5, 'Su hocico alargado con dientes laterales recuerda a una sierra y lo usa para localizar y aturdir presas en el fondo marino.'),
('aguila', 'raya', 'Myliobatiformes', 'Raya águila', 'Myliobatis aquila', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-01', '1.5 m', 'Fondos arenosos costeros', '1–100 m', 'Moderada', 'Moluscos y crustáceos', 3, 'Frecuente en fondos arenosos del litoral español, se alimenta de moluscos y crustáceos que tritura con sus placas dentarias.'),
('manta', 'raya', 'Myliobatiformes', 'Manta raya', 'Mobula birostris', 'Global', ARRAY['global'], 'RAY-02', '6 m', 'Estaciones de limpieza', '0–120 m', 'Moderada', 'Filtrador de plancton', 5, 'La raya más grande, filtradora de plancton. Frecuenta estaciones de limpieza donde permite el acercamiento de buceadores.'),
('latigo', 'raya', 'Myliobatiformes', 'Raya látigo (pastinaca)', 'Dasyatis pastinaca', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-03', '1 m', 'Fondos arenosos someros', '1–60 m', 'Lenta', 'Moluscos y crustáceos', 2, 'Habitual en fondos arenosos poco profundos del Mediterráneo español, a menudo semienterrada. Posee un aguijón venenoso en la cola.'),
('clavos', 'raya', 'Myliobatiformes', 'Raya de clavos', 'Bathytoshia centroura', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-04', '2.5 m', 'Fondos arenosos', '5–60 m', 'Lenta', 'Moluscos', 3, 'Una de las rayas de mayor tamaño en aguas ibéricas, con hileras de espinas dérmicas en el dorso y la cola.'),
('aguila_moteada', 'raya', 'Myliobatiformes', 'Águila moteada', 'Aetobatus narinari', 'Global', ARRAY['caribe','indopacifico'], 'RAY-05', '2.3 m', 'Aguas costeras abiertas', '1–80 m', 'Moderada', 'Moluscos y crustáceos', 3, 'Nada en la columna de agua con aleteos amplios, a menudo en grupo. Muy fotografiada por su patrón de lunares blancos sobre fondo oscuro.'),
('mariposa', 'raya', 'Myliobatiformes', 'Mantelina', 'Gymnura altavela', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-06', '1.8 m', 'Fondos arenosos someros', '5–100 m', 'Lenta', 'Peces y crustáceos', 4, 'Cuerpo muy ancho en forma de rombo, más ancho que largo. Se desplaza semienterrada en fondos de arena somera.'),
('azulina', 'raya', 'Myliobatiformes', 'Raya de manchas azules', 'Taeniura lymma', 'Global', ARRAY['indopacifico'], 'RAY-07', '0.7 m', 'Arrecifes someros', '1–20 m', 'Lenta', 'Moluscos y gusanos', 2, 'Pequeña y muy vistosa, con lunares de un azul eléctrico. Icónica de los arrecifes someros del Indo-Pacífico y muy fotografiada en acuarios.'),
('pelagica', 'raya', 'Myliobatiformes', 'Raya pelágica violeta', 'Pteroplatytrygon violacea', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-08', '0.9 m', 'Aguas abiertas', '0–330 m', 'Moderada', 'Peces pequeños y calamares', 4, 'A diferencia de la mayoría de rayas, vive en aguas abiertas y no en el fondo. Se avista ocasionalmente en aguas pelágicas del Mediterráneo.'),
('comun', 'raya', 'Rajiformes', 'Raya común', 'Raja clavata', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-09', '1.2 m', 'Fondos de arena y grava', '5–300 m', 'Lenta', 'Crustáceos y peces pequeños', 2, 'Raya de fondo con el dorso cubierto de pequeñas espinas ásperas. Muy presente en fondos de arena y grava del litoral atlántico y mediterráneo.'),
('espejos', 'raya', 'Rajiformes', 'Raya de espejos', 'Raja miraletus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-10', '0.6 m', 'Fondos blandos', '1–100 m', 'Lenta', 'Crustáceos', 3, 'Fácil de identificar por dos grandes manchas oscuras en forma de ojo sobre sus aletas pectorales. Común en fondos blandos poco profundos.'),
('santiaguesa', 'raya', 'Rajiformes', 'Raya santiaguesa', 'Rostroraja alba', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-11', '2.3 m', 'Fondos de la plataforma', '30–400 m', 'Lenta', 'Peces y crustáceos', 5, 'Una de las rayas de mayor tamaño de aguas ibéricas, con el hocico muy alargado y puntiagudo. Hoy escasa por la sobrepesca histórica.'),
('mosaica', 'raya', 'Rajiformes', 'Raya mosaica', 'Raja undulata', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-17', '1 m', 'Fondos arenosos y de grava', '5–200 m', 'Lenta', 'Crustáceos y cefalópodos', 4, 'Su dorso presenta un llamativo patrón de manchas y líneas onduladas que le dan nombre. Habita fondos arenosos del Atlántico nororiental y el Mediterráneo occidental; hoy escasa por la presión pesquera.'),
('torpedo', 'raya', 'Torpediniformes', 'Torpedo (tremielga)', 'Torpedo torpedo', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-12', '0.6 m', 'Fondos arenosos someros', '2–50 m', 'Lenta', 'Peces pequeños', 3, 'Capaz de generar descargas eléctricas para aturdir presas o disuadir depredadores. Cuerpo redondeado y liso, típico de fondos arenosos.'),
('torpedomarmoreado', 'raya', 'Torpediniformes', 'Torpedo marmoreado', 'Torpedo marmorata', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-13', '1 m', 'Praderas de posidonia', '2–100 m', 'Lenta', 'Peces pequeños', 3, 'Similar al torpedo común pero con un patrón jaspeado en el dorso. Frecuenta praderas de posidonia y fondos arenosos someros.'),
('guitarra', 'raya', 'Rhinopristiformes', 'Pez guitarra común', 'Rhinobatos rhinobatos', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-14', '1.6 m', 'Fondos arenosos', '5–100 m', 'Lenta', 'Crustáceos y moluscos', 4, 'Forma intermedia entre tiburón y raya, con el cuerpo alargado en forma de guitarra. Vive semienterrado en fondos blandos.'),
('guitarramora', 'raya', 'Rhinopristiformes', 'Guitarra mora', 'Glaucostegus cemiculus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-15', '1.5 m', 'Fondos arenosos costeros', '5–50 m', 'Lenta', 'Crustáceos y moluscos', 4, 'Muy similar al pez guitarra común pero de hocico algo más corto. Comparte los mismos fondos arenosos costeros del sur peninsular.'),
('sierra', 'raya', 'Rhinopristiformes', 'Pez sierra', 'Pristis pristis', 'Global', ARRAY['global'], 'RAY-16', '5.5 m', 'Estuarios y costas someras', '1–40 m', 'Lenta', 'Peces y crustáceos', 5, 'Reconocible por su rostro alargado y dentado. Uno de los peces marinos más amenazados del planeta; hoy es raro incluso en acuarios.'),
('tiburo', 'tiburon', 'Carcharhiniformes', 'Tiburón cabeza de pala', 'Sphyrna tiburo', 'Global', ARRAY['caribe'], 'TBR-28', '1.5 m', 'Costas arenosas y praderas de pastos marinos', '0–80 m', 'Moderada', 'Crustáceos y cefalópodos', 3, 'El único tiburón omnívoro conocido; incluye pastos marinos en su dieta. Frecuente en aguas costeras someras del Atlántico occidental y el Pacífico oriental.'),
('nodrizacolacorta', 'tiburon', 'Orectolobiformes', 'Tiburón nodriza de cola corta', 'Pseudoginglymostoma brevicaudatum', 'Global', ARRAY['indopacifico'], 'TBR-29', '0.75 m', 'Arrecifes de coral someros', '1–30 m', 'Lenta', 'Invertebrados bentónicos', 5, 'La más pequeña de las nodrizas. Vive en arrecifes someros del Indo-Pacífico occidental y es extremadamente rara tanto en libertad como en acuarios.'),
('cigarro', 'tiburon', 'Squaliformes', 'Tiburón cigarro', 'Isistius brasiliensis', 'Global', ARRAY['global'], 'TBR-30', '0.5 m', 'Aguas oceánicas profundas', '85–3500 m', 'Lenta', 'Parásito de grandes vertebrados marinos y cefalópodos', 5, 'Famoso por sus mordidas circulares perfectas en cetáceos, tiburones y hasta cables submarinos. El único tiburón de hábitos semi-parasíticos: se adhiere a su presa, gira y extrae un tapón de carne limpio. Bioluminiscente.'),
('guitarrabocuda', 'raya', 'Rhinopristiformes', 'Guitarra bocuda', 'Rhina ancylostoma', 'Global', ARRAY['indopacifico'], 'RAY-18', '2.7 m', 'Fondos arenosos y de coral', '3–90 m', 'Lenta', 'Crustáceos y moluscos', 4, 'De aspecto imponente con su boca arqueada y crestas de espinas dorsales. Presente en fondos arenosos y coralinos del Indo-Pacífico; habitual en grandes acuarios.'),
('grabata', 'raya', 'Myliobatiformes', 'Raya redonda', 'Taeniura grabata', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-19', '1 m', 'Fondos arenosos y rocosos', '5–50 m', 'Lenta', 'Moluscos y crustáceos', 3, 'Raya de disco redondeado con la cola relativamente corta. Habita fondos arenosos y rocosos del Mediterráneo oriental y el Atlántico africano.'),
('puntanegraarrecife', 'tiburon', 'Carcharhiniformes', 'Tiburón de puntas negras de arrecife', 'Carcharhinus melanopterus', 'Indo-Pacífico', ARRAY['indopacifico'], 'TBR-31', '1.8 m', 'Arrecifes de coral someros y lagunas', '0–20 m', 'Moderada', 'Peces pequeños, cefalópodos y crustáceos', 2, 'Reconocible por las puntas negras de todas sus aletas, sobre todo la dorsal. Habitual en aguas muy someras junto a la orilla de arrecifes y lagunas, donde se le ve nadar en corros al atardecer.'),
('salpa', 'pez', 'Spariformes', 'Salpa', 'Sarpa salpa', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-01', '0.5 m', 'Praderas de posidonia y fondos rocosos someros', '0–70 m', 'Moderada', 'Herbívoro: algas y posidonia', 1, 'Uno de los peces más comunes del Mediterráneo, fácil de reconocer por las líneas doradas a lo largo del cuerpo. Forma grandes bancos que pastan sobre las praderas de posidonia.'),
('sargo', 'pez', 'Spariformes', 'Sargo', 'Diplodus sargus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-02', '0.45 m', 'Fondos rocosos y praderas de posidonia', '0–50 m', 'Moderada', 'Moluscos, crustáceos y algas', 1, 'Cuerpo plateado con bandas verticales oscuras y una franja negra característica en el pedúnculo caudal. Uno de los sargos más comunes en fondos rocosos costeros.'),
('sargoreal', 'pez', 'Spariformes', 'Sargo Imperial', 'Diplodus cervinus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-03', '0.6 m', 'Fondos rocosos', '2–80 m', 'Moderada', 'Invertebrados bentónicos', 3, 'El mayor de los sargos mediterráneos, con bandas verticales más anchas y marcadas que sus parientes. Menos habitual que el sargo común, suele verse en solitario junto a paredes rocosas.'),
('dorada', 'pez', 'Spariformes', 'Dorada', 'Sparus aurata', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-04', '0.7 m', 'Fondos arenosos, praderas y estuarios', '0–150 m', 'Moderada', 'Moluscos y crustáceos, que tritura con sus fuertes dientes', 3, 'Reconocible por la banda dorada entre los ojos que le da nombre. Muy apreciada en gastronomía, se acerca a veces a puertos y zonas costeras poco profundas.'),
('denton', 'pez', 'Spariformes', 'Denton', 'Dentex dentex', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-05', '1 m', 'Fondos rocosos y aguas abiertas cercanas a la costa', '5–200 m', 'Rápida', 'Peces y cefalópodos', 4, 'Depredador activo de perfil frontal muy abrupto, capaz de alcanzar tallas grandes. Escaso en la actualidad por la presión de la pesca, es uno de los peces más buscados por los buceadores.'),
('boga', 'pez', 'Spariformes', 'Boga', 'Boops boops', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-06', '0.3 m', 'Aguas costeras abiertas', '0–350 m', 'Rápida', 'Zooplancton y pequeños invertebrados', 1, 'Pez pequeño y plateado que forma bancos numerosos cerca de la superficie. Uno de los avistamientos más frecuentes al bucear en la costa mediterránea.'),
('mojarra', 'pez', 'Spariformes', 'Mojarra', 'Diplodus vulgaris', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-07', '0.3 m', 'Fondos rocosos y praderas de posidonia', '0–160 m', 'Moderada', 'Pequeños invertebrados y algas', 1, 'Sargo pequeño y muy común, con una única banda oscura junto a la cola bordeada de amarillo. Suele verse en grupos alrededor de rocas y praderas.'),
('castanuela', 'pez', 'Perciformes', 'Castañuela', 'Chromis chromis', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-08', '0.15 m', 'Paredes rocosas', '3–40 m', 'Rápida', 'Zooplancton', 1, 'Pequeño pez oscuro que forma densas nubes sobre las paredes rocosas, alimentándose de plancton en la columna de agua. También se le conoce como damisela; es uno de los pomacéntridos más comunes del Mediterráneo.'),
('mero', 'pez', 'Perciformes', 'Mero', 'Epinephelus marginatus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-09', '1.5 m', 'Cuevas y paredes rocosas', '0–50 m', 'Lenta', 'Peces y crustáceos, cazador de emboscada', 4, 'Gran depredador de cuevas y grietas, curioso y confiado con los buceadores allí donde está protegido. Sus poblaciones se recuperan lentamente tras décadas de sobrepesca.'),
('falsoabadejo', 'pez', 'Perciformes', 'Falso abadejo', 'Epinephelus costae', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-10', '0.9 m', 'Fondos rocosos y de coralígeno', '20–200 m', 'Lenta', 'Peces y crustáceos', 4, 'También llamado mero dorado, es primo cercano del mero común aunque de cuerpo algo más esbelto. Frecuenta fondos de coralígeno más profundos que su pariente.'),
('trescolas', 'pez', 'Perciformes', 'Tres colas', 'Anthias anthias', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-11', '0.24 m', 'Cuevas y paredes con corriente', '15–100 m', 'Moderada', 'Zooplancton', 3, 'Pequeño pez de color rosado y líneas amarillas que debe su nombre a sus grandes aletas pélvicas y caudal. Forma cardúmenes vistosos a la entrada de cuevas y grutas profundas.'),
('corvina', 'pez', 'Perciformes', 'Corvina', 'Sciaena umbra', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-12', '0.5 m', 'Cuevas y paredes en penumbra', '3–50 m', 'Lenta', 'Peces y crustáceos', 3, 'De color oscuro y reflejos cobrizos, se agrupa de día en cuevas y bajo salientes rocosos, casi inmóvil. Antaño muy castigada por la pesca submarina, hoy se recupera en zonas protegidas.'),
('cabrilla', 'pez', 'Perciformes', 'Cabrilla', 'Serranus cabrilla', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-13', '0.25 m', 'Fondos rocosos y praderas de posidonia', '5–300 m', 'Moderada', 'Peces pequeños y crustáceos', 1, 'Pequeño depredador hermafrodita simultáneo, con el cuerpo alargado y bandas verticales rojizas. Uno de los peces más fáciles de encontrar posado sobre rocas y arena.'),
('salmonete', 'pez', 'Perciformes', 'Salmonete de roca', 'Mullus surmuletus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-14', '0.3 m', 'Fondos rocosos y de arena', '5–400 m', 'Moderada', 'Invertebrados del fondo, localizados con sus barbillones', 2, 'De color rojizo y con dos largos barbillones bajo la mandíbula que usa para rastrear el fondo en busca de alimento. Muy apreciado también en gastronomía.'),
('espeton', 'pez', 'Perciformes', 'Espetón', 'Sphyraena viridensis', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-15', '1 m', 'Aguas costeras abiertas', '0–100 m', 'Muy rápida', 'Peces pequeños, depredador activo', 3, 'Barracuda mediterránea de cuerpo torpediforme y dientes afilados. Forma impresionantes bancos verticales casi inmóviles en aguas abiertas, un clásico entre los grandes avistamientos del Mediterráneo.'),
('cabracho', 'pez', 'Scorpaeniformes', 'Cabracho', 'Scorpaena scrofa', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-16', '0.5 m', 'Fondos rocosos, camuflado entre algas y piedras', '5–500 m', 'Muy lenta', 'Peces y crustáceos, caza al acecho', 3, 'Maestro del camuflaje gracias a su piel rugosa y coloración rojiza que imita a las rocas cubiertas de algas. Permanece inmóvil a la espera de que una presa se acerque lo suficiente. Sus espinas son venenosas.'),
('tordo', 'pez', 'Labriformes', 'Tordo', 'Symphodus tinca', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-17', '0.4 m', 'Praderas de posidonia y fondos rocosos', '1–50 m', 'Moderada', 'Invertebrados bentónicos', 2, 'Lábrido robusto de colores variables, del verde al pardo rojizo. El macho construye y vigila un nido de algas donde corteja a las hembras.'),
('julia', 'pez', 'Labriformes', 'Julia', 'Coris julis', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-18', '0.25 m', 'Fondos rocosos y praderas de posidonia', '0–120 m', 'Rápida', 'Pequeños invertebrados', 1, 'Con su franja naranja y azul zigzagueante, es probablemente el pez más avistado en cualquier inmersión mediterránea. Nada rápido y errático entre las rocas.'),
('fredi', 'pez', 'Labriformes', 'Fredi', 'Thalassoma pavo', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-19', '0.2 m', 'Fondos rocosos someros', '0–40 m', 'Rápida', 'Pequeños invertebrados', 2, 'Lábrido de colores vivos —verde, azul y rosa— cada vez más frecuente en el Mediterráneo occidental. También conocido como pez verde, fadrí o senyoreta según la zona.'),
('lisa', 'pez', 'Mugiliformes', 'Lisa', 'Chelon labrosus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-20', '0.7 m', 'Aguas costeras, estuarios y puertos', '0–20 m', 'Moderada', 'Detritos, algas y pequeños invertebrados del sedimento', 1, 'De labios gruesos característicos, forma bancos habituales en puertos y calas poco profundas, donde se alimenta filtrando el sedimento del fondo.'),
('morena', 'pez', 'Anguilliformes', 'Morena', 'Muraena helena', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-21', '1.5 m', 'Grietas y cuevas rocosas', '0–80 m', 'Lenta', 'Peces y cefalópodos', 2, 'Cuerpo serpentiforme con un llamativo patrón marmoleado. Pasa el día asomando la cabeza desde su refugio entre las rocas, abriendo y cerrando la boca para respirar, no como gesto de amenaza.'),
('congrio', 'pez', 'Anguilliformes', 'Congrio', 'Conger conger', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-22', '2 m', 'Cuevas, grietas y restos de naufragios', '0–300 m', 'Lenta', 'Peces, crustáceos y cefalópodos', 2, 'La mayor de las anguilas mediterráneas, de color gris uniforme y sin escamas. Habitual en pecios y grutas, donde puede alcanzar tamaños considerables.'),
('oblada', 'pez', 'Spariformes', 'Oblada', 'Oblada melanura', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-23', '0.3 m', 'Fondos rocosos y praderas de posidonia', '0–100 m', 'Moderada', 'Pequeños invertebrados y algas', 1, 'Fácil de identificar por la mancha negra bordeada de blanco junto a la cola, que imita un ojo para despistar a los depredadores. Forma bancos numerosos y es una de las presencias más habituales en cualquier inmersión mediterránea.'),
('rayatoro', 'raya', 'Myliobatiformes', 'Raya toro', 'Aetomylaeus bovinus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'RAY-20', '2.4 m', 'Fondos arenosos y estuarios costeros', '1–100 m', 'Moderada', 'Moluscos y crustáceos bentónicos', 5, 'Águila marina de morro prominente y larga cola en látigo. Sus poblaciones se han desplomado por la pesca y está catalogada en peligro crítico de extinción.'),
('sierrapequena', 'raya', 'Rhinopristiformes', 'Pez sierra de dientes pequeños', 'Pristis pectinata', 'Global', ARRAY['caribe'], 'RAY-21', '5.5 m', 'Estuarios y aguas costeras someras', '0–25 m', 'Lenta', 'Peces pequeños, localizados con su rostro sensorial', 5, 'Se distingue de la sierra común por tener más dientes rostrales, más pequeños y juntos. Uno de los elasmobranquios más amenazados del planeta, extinguido en gran parte de su antigua área de distribución.'),
('payaso', 'pez', 'Perciformes', 'Pez payaso', 'Amphiprion ocellaris', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-24', '0.11 m', 'Arrecifes de coral, entre los tentáculos de anémonas', '1–15 m', 'Lenta', 'Zooplancton y restos de la anémona huésped', 2, 'Vive en una relación de mutualismo con anémonas urticantes, a las que es inmune gracias a una capa de mucosidad protectora. Uno de los peces de acuario más reconocibles del mundo.'),
('cirujanoazul', 'pez', 'Acanthuriformes', 'Cirujano azul', 'Paracanthurus hepatus', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-25', '0.31 m', 'Arrecifes de coral', '2–40 m', 'Rápida', 'Zooplancton y algas', 2, 'De color azul intenso con una franja negra en forma de paleta, lleva a cada lado de la cola una espina afilada como un bisturí que usa para defenderse.'),
('angelemperador', 'pez', 'Acanthuriformes', 'Pez ángel emperador', 'Pomacanthus imperator', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-26', '0.4 m', 'Arrecifes de coral y paredes rocosas', '1–100 m', 'Moderada', 'Esponjas y tunicados', 3, 'De adulto luce rayas doradas y azules; de joven, un patrón concéntrico blanco y azul completamente distinto que tarda años en transformarse.'),
('pezleon', 'pez', 'Scorpaeniformes', 'Pez león', 'Pterois volitans', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-27', '0.38 m', 'Arrecifes de coral y fondos rocosos', '1–55 m', 'Lenta', 'Peces pequeños y crustáceos', 2, 'Sus vistosas aletas en forma de abanico ocultan espinas venenosas. Introducido accidentalmente en el Caribe y el Atlántico occidental, es hoy una especie invasora sin depredadores naturales allí.'),
('pezglobo', 'pez', 'Tetraodontiformes', 'Pez globo', 'Diodon holocanthus', 'Global', ARRAY['global','canarias','mediterraneo'], 'PEZ-28', '0.5 m', 'Arrecifes y fondos de arena someros', '2–100 m', 'Lenta', 'Moluscos, erizos y crustáceos de caparazón duro', 2, 'Ante una amenaza, traga agua para hincharse hasta triplicar su tamaño y erizar sus espinas, disuadiendo a casi cualquier depredador.'),
('pezerizo', 'pez', 'Tetraodontiformes', 'Pez erizo', 'Diodon hystrix', 'Global', ARRAY['global'], 'PEZ-29', '0.9 m', 'Arrecifes de coral y cuevas', '2–50 m', 'Lenta', 'Moluscos, cangrejos y erizos de mar', 3, 'Primo mayor del pez globo, con espinas más largas y permanentemente erguidas. De hábitos nocturnos, pasa el día escondido en grietas y cuevas.'),
('napoleon', 'pez', 'Labriformes', 'Napoleón', 'Cheilinus undulatus', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-30', '2 m', 'Arrecifes de coral exteriores y pendientes', '1–100 m', 'Lenta', 'Moluscos, erizos, crustáceos y estrellas de mar', 4, 'El mayor de los lábridos, reconocible por la joroba de su frente. Curioso y confiado, es uno de los grandes iconos del buceo en arrecife, aunque está amenazado por la sobrepesca.'),
('pezluna', 'pez', 'Tetraodontiformes', 'Pez luna', 'Mola mola', 'Global', ARRAY['global'], 'PEZ-31', '3 m', 'Aguas abiertas templadas y tropicales', '0–600 m', 'Lenta', 'Medusas y zooplancton gelatinoso', 4, 'El pez óseo más pesado del mundo, con un cuerpo aplanado y sin cola aparente. Sube a la superficie a tomar el sol para que las aves le limpien de parásitos.'),
('caballitocomun', 'pez', 'Syngnathiformes', 'Caballito de mar común', 'Hippocampus hippocampus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-32', '0.15 m', 'Praderas de posidonia y fondos de algas', '0–20 m', 'Muy lenta', 'Pequeños crustáceos planctónicos', 4, 'El macho incuba los huevos en una bolsa ventral hasta el nacimiento de las crías. Se sujeta a las algas con la cola prensil para no ser arrastrado por la corriente.'),
('caballitomediterraneo', 'pez', 'Syngnathiformes', 'Caballito de mar mediterráneo', 'Hippocampus guttulatus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-33', '0.18 m', 'Praderas de posidonia y fondos de algas', '0–30 m', 'Muy lenta', 'Pequeños crustáceos planctónicos', 4, 'Se diferencia del caballito común por su hocico más largo y los filamentos que le cubren la cabeza y el cuerpo, a modo de camuflaje entre las algas.'),
('trompetaoriental', 'pez', 'Syngnathiformes', 'Pez trompeta del Atlántico oriental', 'Aulostomus strigosus', 'Canarias', ARRAY['canarias'], 'PEZ-34', '1 m', 'Fondos rocosos y de coral', '3–30 m', 'Lenta', 'Peces pequeños y crustáceos', 3, 'Cuerpo alargado como un tubo, con la boca al final de un hocico tubular. Caza al acecho, a menudo camuflado verticalmente entre gorgonias o siguiendo a otros peces herbívoros.'),
('pezloro', 'pez', 'Labriformes', 'Pez loro', 'Scarus ghobban', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-35', '0.75 m', 'Arrecifes de coral', '1–30 m', 'Moderada', 'Algas y coral, que tritura con su pico fusionado', 2, 'Sus dientes fusionados en forma de pico raspan las algas del coral, generando gran parte de la arena blanca de los arrecifes tropicales tras digerir el carbonato cálcico.'),
('pezcofre', 'pez', 'Tetraodontiformes', 'Pez cofre', 'Ostracion cubicus', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-36', '0.45 m', 'Arrecifes de coral y lagunas', '1–35 m', 'Lenta', 'Algas, esponjas e invertebrados bentónicos', 3, 'Su cuerpo, encerrado en una coraza ósea rígida en forma de caja, le obliga a nadar aleteando en vez de ondulando. Puede liberar una toxina en la piel si se siente muy amenazado.'),
('pezpiedra', 'pez', 'Scorpaeniformes', 'Pez piedra', 'Synanceia verrucosa', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-37', '0.4 m', 'Fondos rocosos y arrecifes, camuflado entre piedras', '0–40 m', 'Muy lenta', 'Peces y crustáceos, caza al acecho', 4, 'Considerado el pez más venenoso del mundo. Su aspecto de roca cubierta de algas lo hace casi invisible hasta que es demasiado tarde; sus espinas dorsales inyectan un veneno extremadamente doloroso.'),
('anguilajardinera', 'pez', 'Anguilliformes', 'Anguila jardinera', 'Heteroconger longissimus', 'Global', ARRAY['caribe','canarias'], 'PEZ-38', '0.6 m', 'Fondos de arena en corrientes moderadas', '15–45 m', 'Muy lenta', 'Zooplancton arrastrado por la corriente', 3, 'Vive enterrada en colonias de cientos de individuos, cada uno asomando solo la cabeza y el cuerpo superior, como un jardín ondulante que se retrae por completo ante cualquier amenaza.'),
('morenacinta', 'pez', 'Anguilliformes', 'Morena cinta', 'Rhinomuraena quaesita', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-39', '1.3 m', 'Fondos de arena y escombros coralinos', '2–60 m', 'Lenta', 'Peces pequeños', 3, 'Cambia de sexo y color a lo largo de su vida: nace macho y negro, pasa a macho azul, y termina como hembra amarilla. Sus fosas nasales en forma de cinta le dan el nombre.'),
('vieja', 'pez', 'Labriformes', 'Vieja', 'Sparisoma cretense', 'Canarias', ARRAY['canarias'], 'PEZ-40', '0.5 m', 'Fondos rocosos y praderas marinas', '0–50 m', 'Moderada', 'Algas, que raspa de las rocas con su pico', 1, 'Único representante de los peces loro en aguas españolas. Las hembras son rojizas y los machos, tras cambiar de sexo, adquieren tonos verdosos y azulados.'),
('abade', 'pez', 'Perciformes', 'Abade', 'Mycteroperca fusca', 'Canarias', ARRAY['canarias'], 'PEZ-41', '0.6 m', 'Fondos rocosos y cuevas', '5–60 m', 'Lenta', 'Peces y crustáceos', 3, 'Mero esbelto endémico de Macaronesia, de color pardo con la aleta caudal recortada. Confiado y curioso con los buceadores en zonas protegidas de Canarias.'),
('fulanegra', 'pez', 'Perciformes', 'Fula negra', 'Abudefduf luridus', 'Canarias', ARRAY['canarias'], 'PEZ-42', '0.2 m', 'Fondos rocosos someros', '0–15 m', 'Rápida', 'Algas y pequeños invertebrados', 1, 'Damisela oscura endémica de Macaronesia, territorial y agresiva pese a su pequeño tamaño: defiende con fiereza su parcela de alga frente a otros peces.'),
('fulablanca', 'pez', 'Perciformes', 'Fula blanca', 'Chromis limbata', 'Canarias', ARRAY['canarias'], 'PEZ-43', '0.14 m', 'Paredes rocosas', '1–35 m', 'Rápida', 'Zooplancton', 1, 'Damisela de color pardo con la base de la cola blanca, muy común en Canarias. Forma nubes densas sobre las paredes rocosas, sustituyendo aquí a la castañuela mediterránea.'),
('catalufa', 'pez', 'Perciformes', 'Catalufa', 'Heteropriacanthus cruentatus', 'Canarias', ARRAY['canarias'], 'PEZ-44', '0.3 m', 'Cuevas y paredes rocosas en penumbra', '3–70 m', 'Lenta', 'Zooplancton y pequeños invertebrados nocturnos', 3, 'De grandes ojos adaptados a la escasa luz y color rojizo intenso, pasa el día inmóvil en cuevas y grietas, y sale a alimentarse al anochecer.'),
('morenanegra', 'pez', 'Anguilliformes', 'Morena negra', 'Muraena augusti', 'Canarias', ARRAY['canarias'], 'PEZ-45', '1 m', 'Grietas y cuevas rocosas', '0–40 m', 'Lenta', 'Peces y crustáceos', 2, 'Endémica de Macaronesia, se distingue de la morena mediterránea por su color más oscuro y uniforme. Comparte el mismo hábito de asomar la cabeza desde su refugio para respirar.'),
('tamboril', 'pez', 'Tetraodontiformes', 'Tamboril', 'Sphoeroides marmoratus', 'Canarias', ARRAY['canarias'], 'PEZ-46', '0.25 m', 'Fondos de arena y roca someros', '0–30 m', 'Lenta', 'Moluscos, crustáceos y algas', 2, 'Pequeño pez globo de patrón moteado, capaz de hincharse tragando agua cuando se siente amenazado. Su carne y vísceras contienen tetrodotoxina, altamente tóxica.'),
('trompetero', 'pez', 'Syngnathiformes', 'Trompetero', 'Macroramphosus scolopax', 'Canarias', ARRAY['canarias'], 'PEZ-47', '0.2 m', 'Fondos de arena y aguas semipelágicas', '25–600 m', 'Moderada', 'Zooplancton y pequeños invertebrados bentónicos', 2, 'De cuerpo comprimido y hocico tubular muy alargado, forma bancos numerosos cerca del fondo. La primera espina de su aleta dorsal es larga y erguida.'),
('ballesta', 'pez', 'Tetraodontiformes', 'Pez ballesta', 'Balistes capriscus', 'Canarias', ARRAY['canarias'], 'PEZ-48', '0.6 m', 'Fondos rocosos y de arena', '3–55 m', 'Moderada', 'Moluscos, erizos y crustáceos de caparazón duro', 2, 'Puede trabar su primera espina dorsal en posición erguida como un mecanismo de ballesta, encajándose en una grieta para que ningún depredador pueda extraerlo.'),
('rubiovolador', 'pez', 'Dactylopteriformes', 'Rubio volador', 'Dactylopterus volitans', 'Canarias', ARRAY['canarias'], 'PEZ-49', '0.5 m', 'Fondos de arena y fango', '3–100 m', 'Lenta', 'Crustáceos e invertebrados bentónicos', 2, 'Sus enormes aletas pectorales, como alas de mariposa, no le permiten volar de verdad, pero las despliega para intimidar a los depredadores y "camina" por el fondo con los radios inferiores.'),
('morenafogosa', 'pez', 'Anguilliformes', 'Morena fogosa', 'Enchelycore anatina', 'Canarias', ARRAY['canarias'], 'PEZ-50', '0.8 m', 'Grietas y cuevas en fondos rocosos', '2–40 m', 'Lenta', 'Peces y cefalópodos', 3, 'También llamada morena picopato, por su mandíbula curvada que le impide cerrar la boca del todo. Endémica de Macaronesia, de colores rojizos con manchas amarillas.'),
('morenaleopardo', 'pez', 'Anguilliformes', 'Morena leopardo', 'Gymnothorax favagineus', 'Indo-Pacífico', ARRAY['indopacifico'], 'PEZ-76', '3 m', 'Arrecifes de coral y cuevas rocosas', '1–50 m', 'Lenta', 'Peces, pulpos y crustáceos', 3, 'También llamada morena de puntos negros, por el intrincado dibujo de manchas oscuras sobre fondo claro que cubre todo su cuerpo. Una de las morenas de mayor tamaño, puede superar los 3 metros de longitud.'),
('reyezuelo', 'pez', 'Perciformes', 'Reyezuelo', 'Apogon imberbis', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-51', '0.14 m', 'Cuevas y grietas en penumbra', '3–200 m', 'Lenta', 'Zooplancton nocturno', 2, 'Pequeño pez cardinal de color rojo intenso y grandes ojos, típico de la entrada de cuevas. El macho incuba los huevos en la boca hasta la eclosión.'),
('pejerrey', 'pez', 'Atheriniformes', 'Pejerrey mediterráneo', 'Atherina boyeri', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-52', '0.13 m', 'Aguas costeras someras, lagunas y estuarios', '0–10 m', 'Rápida', 'Zooplancton', 1, 'Pequeño pez plateado que forma bancos muy numerosos cerca de la orilla, con una franja plateada brillante a lo largo del cuerpo. Tolera bien aguas salobres.'),
('pezperro', 'pez', 'Labriformes', 'Pez perro', 'Bodianus scrofa', 'Canarias', ARRAY['canarias'], 'PEZ-53', '0.5 m', 'Fondos rocosos y de coralígeno', '10–200 m', 'Moderada', 'Moluscos, crustáceos y erizos', 3, 'Lábrido de gran tamaño y colores vivos —rosa, amarillo y verde— endémico del Atlántico oriental. Rompe el caparazón de sus presas con sus fuertes dientes.'),
('podas', 'pez', 'Pleuronectiformes', 'Podas', 'Bothus podas', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-54', '0.2 m', 'Fondos de arena y fango someros', '2–100 m', 'Lenta', 'Pequeños peces y crustáceos', 2, 'Pez plano que, como todos los bótidos, tiene ambos ojos en el lado izquierdo del cuerpo. Se entierra en la arena dejando solo los ojos al descubierto, a la espera de presas.'),
('gallinita', 'pez', 'Tetraodontiformes', 'Gallinita', 'Canthigaster capistrata', 'Canarias', ARRAY['canarias'], 'PEZ-55', '0.1 m', 'Fondos de arena y roca', '5–70 m', 'Moderada', 'Invertebrados bentónicos y algas', 2, 'El pez globo más pequeño de las aguas canarias, con un patrón de puntos azules característico. A diferencia de otros tetraodóntidos, nada de forma ágil y activa.'),
('tamborilespinoso', 'pez', 'Tetraodontiformes', 'Tamboril espinoso', 'Chilomycterus reticulatus', 'Canarias', ARRAY['canarias'], 'PEZ-77', '0.55 m', 'Fondos rocosos y de arena', '0–30 m', 'Lenta', 'Moluscos, crustáceos y erizos', 4, 'Mucho mayor que el tamboril común, con el cuerpo cubierto de espinas cortas fijas (no erizables) y un patrón de manchas negras sobre fondo gris claro. Especie protegida en Canarias.'),
('chavito', 'pez', 'Zeiformes', 'Chavito', 'Capros aper', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-56', '0.12 m', 'Fondos rocosos y de coralígeno profundos', '20–600 m', 'Lenta', 'Zooplancton', 3, 'Pequeño pez de cuerpo comprimido y color rosado intenso, con una boca protráctil que proyecta hacia delante como un tubo para capturar plancton.'),
('dorado', 'pez', 'Perciformes', 'Dorado', 'Coryphaena hippurus', 'Global', ARRAY['global'], 'PEZ-57', '2 m', 'Aguas pelágicas abiertas, cerca de objetos flotantes', '0–85 m', 'Muy rápida', 'Peces voladores, calamares y crustáceos', 3, 'Uno de los peces más rápidos y de colores más vivos del océano —verde, azul y dorado—, que se apagan rápidamente al salir del agua. Nada en grupos bajo objetos flotantes.'),
('lubina', 'pez', 'Perciformes', 'Lubina', 'Dicentrarchus labrax', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-58', '1 m', 'Aguas costeras, estuarios y puertos', '0–100 m', 'Rápida', 'Peces pequeños y crustáceos', 2, 'Depredador plateado muy apreciado en gastronomía, frecuenta rompientes y desembocaduras donde caza pequeños peces. Puede vivir tanto en agua salada como salobre.'),
('baila', 'pez', 'Perciformes', 'Baila', 'Dicentrarchus punctatus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-59', '0.6 m', 'Aguas costeras y estuarios', '0–50 m', 'Rápida', 'Peces pequeños y crustáceos', 2, 'Muy parecida a la lubina, se distingue por las manchas oscuras que salpican sus costados. Suele formar bancos más numerosos que su pariente.'),
('raspallon', 'pez', 'Spariformes', 'Raspallón', 'Diplodus annularis', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-60', '0.2 m', 'Fondos de arena y praderas de posidonia', '0–30 m', 'Moderada', 'Pequeños invertebrados y algas', 1, 'El más pequeño de los sargos mediterráneos, con un anillo negro característico en el pedúnculo caudal. Muy común en fondos someros de arena.'),
('sargopicudo', 'pez', 'Spariformes', 'Sargo picudo', 'Diplodus puntazzo', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-61', '0.6 m', 'Fondos rocosos y de arena', '0–160 m', 'Moderada', 'Moluscos y crustáceos', 2, 'Se diferencia del resto de sargos por su hocico puntiagudo, adaptado a hurgar en la arena en busca de moluscos e invertebrados enterrados.'),
('salvariego', 'pez', 'Trachiniformes', 'Salvariego', 'Echiichthys vipera', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-62', '0.15 m', 'Fondos de arena someros', '1–150 m', 'Muy lenta', 'Pequeños peces y crustáceos', 2, 'Pasa el día enterrado en la arena con solo los ojos y las espinas dorsales venenosas al descubierto. Su picadura es muy dolorosa, típica de bañistas que lo pisan sin querer.'),
('meroguasa', 'pez', 'Perciformes', 'Mero guasa', 'Epinephelus itajara', 'Global', ARRAY['caribe'], 'PEZ-63', '2.5 m', 'Manglares, arrecifes y pecios', '1–100 m', 'Lenta', 'Peces, crustáceos y tortugas pequeñas', 5, 'Uno de los peces óseos más grandes de los arrecifes, capaz de superar los 300 kg. En peligro crítico por la sobrepesca; protegido en gran parte de su área de distribución.'),
('bacoreta', 'pez', 'Scombriformes', 'Bacoreta', 'Euthynnus alletteratus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-64', '1 m', 'Aguas costeras y pelágicas', '0–100 m', 'Muy rápida', 'Peces pequeños y crustáceos planctónicos', 2, 'Pariente pequeño del atún, con un característico dibujo de líneas onduladas en el dorso. Caza en bancos veloces cerca de la superficie.'),
('pezvolador', 'pez', 'Beloniformes', 'Pez volador común', 'Exocoetus volitans', 'Global', ARRAY['global'], 'PEZ-65', '0.3 m', 'Aguas pelágicas cálidas de superficie', '0–10 m', 'Muy rápida', 'Zooplancton', 2, 'Sus enormes aletas pectorales, a modo de alas, le permiten planear varios metros sobre la superficie del agua para escapar de depredadores como el dorado.'),
('gobionegro', 'pez', 'Gobiiformes', 'Gobio negro', 'Gobius niger', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-66', '0.18 m', 'Fondos de arena y fango, praderas marinas', '0–75 m', 'Lenta', 'Pequeños invertebrados bentónicos', 1, 'Pequeño pez de fondo que descansa apoyado sobre sus aletas pélvicas fusionadas en forma de ventosa. El macho vigila los huevos hasta la eclosión.'),
('gobioroca', 'pez', 'Gobiiformes', 'Gobio de roca', 'Gobius paganellus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-67', '0.12 m', 'Pozas de marea y fondos rocosos someros', '0–15 m', 'Lenta', 'Pequeños invertebrados y algas', 1, 'Habitual en las pozas de marea de la zona intermareal, donde permanece inmóvil apoyado en las rocas gracias a su aleta ventral en forma de disco adhesivo.'),
('morion', 'pez', 'Anguilliformes', 'Murión', 'Gymnothorax unicolor', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-68', '0.65 m', 'Grietas y cuevas en fondos rocosos', '0–40 m', 'Lenta', 'Peces y crustáceos', 3, 'Morena de color pardo uniforme, sin el moteado de la morena común. Más esquiva y de hábitos más nocturnos que su pariente, suele pasar desapercibida.'),
('chopa', 'pez', 'Perciformes', 'Chopa', 'Kyphosus sectatrix', 'Global', ARRAY['caribe','canarias'], 'PEZ-69', '0.45 m', 'Fondos rocosos someros', '0–30 m', 'Moderada', 'Algas', 1, 'Pez herbívoro plateado que forma bancos numerosos junto a las rocas costeras, donde pasta sobre las algas incrustantes durante el día.'),
('merlo', 'pez', 'Labriformes', 'Merlo', 'Labrus merula', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-70', '0.4 m', 'Fondos rocosos y praderas de posidonia', '0–50 m', 'Moderada', 'Moluscos, crustáceos y erizos', 2, 'Lábrido robusto de color pardo oscuro casi negro, con la boca gruesa característica del género. Suele verse en solitario cerca de paredes rocosas.'),
('gorrion', 'pez', 'Labriformes', 'Gorrión', 'Labrus mixtus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-71', '0.4 m', 'Fondos rocosos y de coralígeno', '5–200 m', 'Moderada', 'Moluscos y crustáceos', 3, 'Uno de los peces más coloridos del Mediterráneo: el macho luce un intenso patrón azul y naranja, mientras que la hembra es rosada con manchas oscuras.'),
('rapenegro', 'pez', 'Lophiiformes', 'Rape negro', 'Lophius budegassa', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-72', '1 m', 'Fondos de arena y fango', '20–800 m', 'Muy lenta', 'Peces, atraídos con su señuelo dorsal', 3, 'Se distingue del rape común por el peritoneo negro que recubre su cavidad abdominal. Camuflado en el fondo, agita un filamento con forma de cebo para atraer a sus presas.'),
('rapecomun', 'pez', 'Lophiiformes', 'Rape común', 'Lophius piscatorius', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-73', '2 m', 'Fondos de arena y fango', '0–1000 m', 'Muy lenta', 'Peces, atraídos con su señuelo dorsal', 3, 'Cabeza enorme y aplanada casi tan ancha como el resto del cuerpo, perfectamente camuflada entre el sedimento. Caza al acecho, inmóvil, agitando su "caña" dorsal como cebo.'),
('herrera', 'pez', 'Spariformes', 'Herrera', 'Lithognathus mormyrus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'PEZ-74', '0.55 m', 'Fondos de arena costeros', '0–50 m', 'Moderada', 'Invertebrados enterrados en la arena', 1, 'Cuerpo plateado con bandas verticales doradas y hocico puntiagudo, adaptado a hurgar en la arena en busca de gusanos y pequeños moluscos.'),
('medusaluna', 'medusa', 'Semaeostomeae', 'Medusa luna', 'Aurelia aurita', 'Global', ARRAY['global','mediterraneo','cantabrico'], 'MED-01', '0.3 m', 'Aguas costeras y bahías', '0–20 m', 'Muy lenta', 'Zooplancton', 1, 'Translúcida, con cuatro anillos en forma de herradura visibles a través de la umbrela. Una de las medusas más comunes y reconocibles del mundo, con picadura muy leve.'),
('huevofrito', 'medusa', 'Rhizostomeae', 'Medusa huevo frito', 'Cotylorhiza tuberculata', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'MED-02', '0.35 m', 'Aguas costeras cálidas', '0–20 m', 'Muy lenta', 'Zooplancton', 1, 'Debe su nombre a la umbrela amarillenta con un abultamiento central que recuerda a una yema de huevo frito. Su picadura es leve o casi imperceptible.'),
('medusacompas', 'medusa', 'Semaeostomeae', 'Medusa compás', 'Chrysaora hysoscella', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'MED-03', '0.3 m', 'Aguas costeras y pelágicas someras', '0–30 m', 'Lenta', 'Zooplancton y peces pequeños', 2, 'Su umbrela translúcida está marcada con 16 franjas radiales oscuras, como las agujas de una brújula. Picadura moderadamente urticante.'),
('ortigapacifico', 'medusa', 'Semaeostomeae', 'Medusa ortiga del Pacífico', 'Chrysaora fuscescens', 'Global', ARRAY['global'], 'MED-04', '0.5 m', 'Aguas costeras templadas', '0–30 m', 'Lenta', 'Zooplancton y peces pequeños', 2, 'De umbrela dorada y largos tentáculos oscuros, forma enjambres espectaculares en la costa del Pacífico. Muy popular en acuarios por su elegante nado ondulante.'),
('medusaclavel', 'medusa', 'Semaeostomeae', 'Medusa clavel', 'Pelagia noctiluca', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'MED-05', '0.12 m', 'Aguas pelágicas abiertas', '0–100 m', 'Lenta', 'Zooplancton y peces pequeños', 2, 'También llamada medusa fosforescente por su bioluminiscencia, es la principal responsable de las picaduras en las costas mediterráneas durante el verano.'),
('melenaleon', 'medusa', 'Semaeostomeae', 'Medusa melena de león', 'Cyanea capillata', 'Global', ARRAY['global','cantabrico'], 'MED-06', '2 m', 'Aguas frías y templadas de superficie', '0–20 m', 'Lenta', 'Zooplancton, peces pequeños y otras medusas', 3, 'La medusa más grande conocida: sus tentáculos, agrupados en mechones como una melena, pueden superar los 30 metros de longitud en los ejemplares más grandes.'),
('bolacanon', 'medusa', 'Rhizostomeae', 'Medusa bola de cañón', 'Stomolophus meleagris', 'Global', ARRAY['caribe'], 'MED-07', '0.25 m', 'Aguas costeras someras y estuarios', '0–20 m', 'Lenta', 'Zooplancton', 2, 'De umbrela esférica y firme como una bola de cañón, carece de tentáculos marginales largos. Su picadura es prácticamente inofensiva para el ser humano.'),
('medusainvertida', 'medusa', 'Rhizostomeae', 'Medusa invertida', 'Cassiopea andromeda', 'Global', ARRAY['indopacifico','mediterraneo'], 'MED-08', '0.3 m', 'Fondos someros de manglar y lagunas', '0–5 m', 'Sedentaria', 'Fotosíntesis de algas simbióticas y zooplancton', 2, 'A diferencia del resto de medusas, reposa boca arriba sobre el fondo, con los brazos hacia el sol para alimentar a las algas simbióticas que viven en su tejido.'),
('medusacristal', 'medusa', 'Leptothecata', 'Medusa de cristal', 'Aequorea victoria', 'Global', ARRAY['global'], 'MED-09', '0.1 m', 'Aguas costeras templadas', '0–30 m', 'Muy lenta', 'Zooplancton', 3, 'Casi completamente transparente, bioluminiscente en azul-verde. La proteína que le da ese brillo (GFP) revolucionó la biología al usarse como marcador fluorescente en laboratorios de todo el mundo.'),
('medusamoteada', 'medusa', 'Rhizostomeae', 'Medusa moteada', 'Phyllorhiza punctata', 'Global', ARRAY['indopacifico','mediterraneo'], 'MED-10', '0.5 m', 'Aguas costeras cálidas', '0–15 m', 'Lenta', 'Zooplancton', 2, 'También llamada medusa australiana, tiene la umbrela salpicada de puntos blancos. Especie muy exhibida en grandes acuarios por su llamativa silueta.'),
('carabelaportuguesa', 'medusa', 'Siphonophorae', 'Carabela portuguesa', 'Physalia physalis', 'Canarias', ARRAY['canarias','global'], 'MED-11', '0.3 m', 'Superficie de aguas pelágicas, arrastrada por el viento', '0–1 m', 'A la deriva', 'Peces pequeños y zooplancton', 2, 'No es una medusa verdadera sino una colonia de organismos especializados. Su flotador azulado sobresale del agua como una vela; sus tentáculos, de hasta 30 metros, causan picaduras muy dolorosas.'),
('aguamala', 'medusa', 'Rhizostomeae', 'Aguamala', 'Rhizostoma pulmo', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'MED-12', '0.6 m', 'Aguas costeras y pelágicas someras', '0–30 m', 'Lenta', 'Zooplancton', 1, 'Gran medusa de umbrela blanquecina bordeada de violeta y sin tentáculos marginales largos. Pese a su tamaño, su picadura es leve.'),
('bogavante', 'crustaceo', 'Decapoda', 'Bogavante europeo', 'Homarus gammarus', 'Global', ARRAY['cantabrico','mediterraneo'], 'CRU-01', '0.5 m', 'Fondos rocosos y grietas', '0–150 m', 'Lenta', 'Moluscos, crustáceos y carroña', 3, 'De color azulado con manchas claras (que se vuelve rojo solo al cocinarlo), es uno de los crustáceos más apreciados en gastronomía. Defiende su refugio con sus grandes pinzas asimétricas.'),
('langosta', 'crustaceo', 'Decapoda', 'Langosta común', 'Palinurus elephas', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'CRU-02', '0.5 m', 'Fondos rocosos y cuevas', '5–150 m', 'Moderada', 'Moluscos, erizos y pequeños invertebrados', 3, 'A diferencia del bogavante, carece de grandes pinzas y se defiende con sus largas antenas espinosas. De hábitos nocturnos, de día se refugia en grietas y cuevas.'),
('centollo', 'crustaceo', 'Decapoda', 'Centollo', 'Maja squinado', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'CRU-03', '0.2 m', 'Fondos rocosos y de arena', '0–100 m', 'Lenta', 'Algas, moluscos y carroña', 2, 'Cangrejo de caparazón espinoso que a menudo se camufla decorándolo con algas y esponjas. Muy apreciado en la gastronomía costera española.'),
('bueymar', 'crustaceo', 'Decapoda', 'Buey de mar', 'Cancer pagurus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'CRU-04', '0.25 m', 'Fondos rocosos y de arena', '0–100 m', 'Lenta', 'Moluscos, crustáceos y carroña', 2, 'Cangrejo robusto de caparazón oval con el borde ondulado, como una empanadilla. Sus grandes pinzas de puntas negras pueden ejercer una fuerza considerable.'),
('necora', 'crustaceo', 'Decapoda', 'Nécora', 'Necora puber', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'CRU-05', '0.08 m', 'Fondos rocosos someros', '0–70 m', 'Rápida', 'Moluscos, algas y pequeños invertebrados', 2, 'Pequeño cangrejo nadador de caparazón velludo y ojos rojos, con el último par de patas aplanado en forma de remo. Muy activo y agresivo pese a su tamaño.'),
('cangrejoarania', 'crustaceo', 'Decapoda', 'Cangrejo araña japonés', 'Macrocheira kaempferi', 'Indo-Pacífico', ARRAY['indopacifico'], 'CRU-06', '3.7 m', 'Fondos profundos de arena y fango', '50–600 m', 'Muy lenta', 'Moluscos, carroña y algas', 4, 'El artrópodo vivo más grande del mundo: con las patas extendidas puede superar los 3.5 metros. Puede vivir más de 50 años y es una de las estrellas de los grandes acuarios.'),
('cangrejoherradura', 'crustaceo', 'Xiphosura', 'Cangrejo herradura', 'Limulus polyphemus', 'Global', ARRAY['global'], 'CRU-07', '0.6 m', 'Fondos de arena y fango costeros', '0–30 m', 'Lenta', 'Moluscos y gusanos marinos', 3, 'Pese al nombre, no es un crustáceo sino un pariente cercano de las arañas, prácticamente sin cambios desde hace más de 400 millones de años. Su sangre azul es clave en pruebas médicas de detección de bacterias.'),
('ermitano', 'crustaceo', 'Decapoda', 'Cangrejo ermitaño', 'Pagurus bernhardus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'CRU-08', '0.1 m', 'Fondos de arena, roca y pozas de marea', '0–100 m', 'Lenta', 'Carroña, algas y pequeños invertebrados', 1, 'Al carecer de caparazón propio en el abdomen, ocupa conchas vacías de caracoles marinos, cambiando de "casa" a medida que crece.'),
('camaronlimpiador', 'crustaceo', 'Decapoda', 'Camarón limpiador', 'Lysmata amboinensis', 'Indo-Pacífico', ARRAY['indopacifico'], 'CRU-09', '0.06 m', 'Arrecifes de coral, cerca de anémonas', '1–40 m', 'Lenta', 'Parásitos y tejido muerto de otros peces', 2, 'Instala pequeñas "estaciones de limpieza" en el arrecife donde los peces, incluso depredadores, acuden a que les retire parásitos y piel muerta.'),
('gambamantis', 'crustaceo', 'Stomatopoda', 'Gamba mantis', 'Odontodactylus scyllarus', 'Indo-Pacífico', ARRAY['indopacifico'], 'CRU-10', '0.18 m', 'Arrecifes de coral y fondos de arena', '3–40 m', 'Rápida', 'Moluscos, cangrejos y peces pequeños', 3, 'Golpea a sus presas con sus apéndices delanteros a una velocidad tan alta que genera burbujas de cavitación capaces de romper el cristal de un acuario. Posee uno de los sistemas visuales más complejos del reino animal.'),
('percebe', 'crustaceo', 'Sessilia', 'Percebe', 'Pollicipes pollicipes', 'Mediterráneo', ARRAY['mediterraneo','cantabrico'], 'CRU-11', '0.07 m', 'Rocas expuestas al oleaje intermareal', '0–2 m', 'Sedentario', 'Filtrador de plancton', 3, 'Crustáceo sésil que pasa toda su vida adulta fijado a rocas batidas por el oleaje, filtrando plancton con sus apéndices plumosos. Su recolección es una de las más peligrosas de la pesca artesanal.'),
('cangrejomoro', 'crustaceo', 'Decapoda', 'Cangrejo moro', 'Grapsus adscensionis', 'Canarias', ARRAY['canarias'], 'CRU-12', '0.08 m', 'Rocas volcánicas del litoral batidas por el oleaje', '0–2 m', 'Muy rápida', 'Algas y carroña', 1, 'De colores vivos rojizos y azulados, es extraordinariamente ágil trepando por las rocas de la orilla, escapando de un salto en cuanto detecta movimiento.'),
('tortugaboba', 'reptil', 'Testudines', 'Tortuga boba', 'Caretta caretta', 'Global', ARRAY['mediterraneo','cantabrico','canarias','caribe','indopacifico'], 'REP-01', '0.9 m', 'Aguas costeras y pelágicas', '0–50 m', 'Moderada', 'Medusas, moluscos y crustáceos', 3, 'La tortuga marina más común en el Mediterráneo, donde también anida. Reconocible por su gran cabeza y su caparazón acorazonado de tono rojizo-pardo; puede recorrer miles de kilómetros entre sus zonas de alimentación y de puesta.'),
('tortugaverde', 'reptil', 'Testudines', 'Tortuga verde', 'Chelonia mydas', 'Global', ARRAY['canarias','caribe','indopacifico'], 'REP-02', '1 m', 'Praderas marinas, arrecifes y aguas costeras someras', '0–40 m', 'Moderada', 'Algas y fanerógamas marinas', 3, 'Se diferencia de la tortuga boba por su cabeza más pequeña y una sola pareja de escamas prefrontales. El adulto es casi exclusivamente herbívoro, alimentándose de fanerógamas marinas y algas, dieta que da nombre a la especie por el tono verdoso de su grasa corporal.'),
('cangrejoaranacanarias', 'crustaceo', 'Decapoda', 'Cangrejo araña', 'Stenorhynchus lanceolatus', 'Canarias', ARRAY['canarias'], 'CRU-13', '0.2 m', 'Fondos rocosos, a menudo junto a erizos diadema', '0–100 m', 'Lenta', 'Algas y pequeños invertebrados', 2, 'Cuerpo triangular pequeño con dos largas pinzas y ocho patas finas que, extendidas, pueden alcanzar los 20 cm. De comportamiento tranquilo, no suele esconderse ante la presencia de un buceador.'),
('maranuela', 'crustaceo', 'Decapoda', 'Marañuela', 'Percnon gibbesi', 'Canarias', ARRAY['canarias'], 'CRU-14', '0.04 m', 'Fondos rocosos someros con algas, junto a erizos', '0–4 m', 'Muy rápida', 'Algas filamentosas y calcáreas', 2, 'También llamada cangrejo araña, aunque no está emparentada con él: cuerpo plano y ovalado de tonos pardo-rojizos con líneas azuladas y verdes fosforescentes. Ante cualquier amenaza escapa en zigzag entre las púas de los erizos de mar.'),
('cigarramar', 'crustaceo', 'Decapoda', 'Cigarra de mar', 'Scyllarides latus', 'Mediterráneo', ARRAY['mediterraneo','canarias'], 'CRU-15', '0.45 m', 'Fondos rocosos, cuevas y grietas', '4–100 m', 'Lenta', 'Moluscos y erizos de mar', 4, 'También llamada langosta canaria. Sin las largas antenas de la langosta común, tiene en su lugar dos placas aplanadas a modo de antenas cortas. De hábitos nocturnos, pasa el día escondida en cuevas y grietas.'),
('roncador', 'pez', 'Perciformes', 'Roncador', 'Pomadasys incisus', 'Mediterráneo', ARRAY['mediterraneo','cantabrico','canarias'], 'PEZ-75', '0.5 m', 'Fondos rocosos y de arena costeros', '0–50 m', 'Moderada', 'Invertebrados bentónicos', 2, 'Forma bancos numerosos que pueden mantenerse en el mismo punto durante años, convirtiéndose en un atractivo propio para el buceo. Debe su nombre al sonido similar a un ronquido que emite al ser capturado.'),
('nudibranquiopinto', 'molusco', 'Nudibranchia', 'Nudibranquio pinto', 'Felimare picta', 'Canarias', ARRAY['canarias'], 'MOL-01', '35 mm', 'Fondos rocosos en penumbra', '0–50 m', 'Muy lenta', 'Esponjas del género Sarcotragus', 2, 'Uno de los nudibranquios más comunes y vistosos de Canarias: cuerpo oscuro cubierto por una densa red de líneas y motas amarillas, con rinóforos y branquia de puntas azules. Se desplaza raspando esponjas con su rádula.'),
('bermudella', 'molusco', 'Nudibranchia', 'Bermudella', 'Bermudella polycerelloides', 'Canarias', ARRAY['canarias'], 'MOL-02', '15 mm', 'Fondos rocosos someros', '0–30 m', 'Muy lenta', 'Briozoos', 4, 'Pequeño nudibranquio descrito originalmente en Canarias. Como el resto de Polyceridae, se alimenta raspando colonias de briozoos incrustantes.'),
('crimora', 'molusco', 'Nudibranchia', 'Crimora', 'Crimora papillata', 'Canarias', ARRAY['canarias'], 'MOL-03', '30 mm', 'Fondos rocosos someros', '0–30 m', 'Muy lenta', 'Briozoos como Flustra foliacea y Membranipora membranacea', 3, 'Cuerpo blanquecino cubierto de papilas ramificadas que le sirven de camuflaje entre las colonias de briozoos de las que se alimenta.'),
('kaloplocamus', 'molusco', 'Nudibranchia', 'Nudibranquio de flecos', 'Kaloplocamus ramosus', 'Canarias', ARRAY['canarias'], 'MOL-04', '30 mm', 'Fondos rocosos y cuevas', '0–40 m', 'Muy lenta', 'Briozoos', 3, 'Conocido como "tasselled nudibranch" por los mechones ramificados que cubren su dorso, entre los que puede esconder también sus branquias.'),
('tambjaceutae', 'molusco', 'Nudibranchia', 'Tambja de Ceuta', 'Tambja ceutae', 'Canarias', ARRAY['canarias'], 'MOL-05', '40 mm', 'Fondos rocosos y cuevas', '0–40 m', 'Muy lenta', 'Briozoos', 3, 'Descrito originalmente en Ceuta, en el estrecho de Gibraltar. De color verdoso a azulado con manchas amarillas, típico de los Polyceridae que se alimentan de briozoos.'),
('felimaretricolor', 'molusco', 'Nudibranchia', 'Nudibranquio tricolor', 'Felimare tricolor', 'Canarias', ARRAY['canarias'], 'MOL-06', '50 mm', 'Fondos rocosos', '0–40 m', 'Muy lenta', 'Esponjas', 3, 'Cuerpo azul intenso bordeado por una línea amarillo-anaranjada en el manto, uno de los patrones más vistosos entre los Felimare de Canarias.'),
('felimareverdosa', 'molusco', 'Nudibranchia', 'Felimare verdosa', 'Felimare bilineata', 'Canarias', ARRAY['canarias'], 'MOL-07', '40 mm', 'Fondos rocosos', '0–40 m', 'Muy lenta', 'Esponjas', 3, 'Forma de color verdoso azulado de Felimare bilineata, con dos líneas longitudinales que recorren el dorso a lo largo del cuerpo.'),
('felimidapurpurea', 'molusco', 'Nudibranchia', 'Felimida púrpura', 'Felimida purpurea', 'Canarias', ARRAY['canarias'], 'MOL-08', '40 mm', 'Fondos rocosos', '0–40 m', 'Muy lenta', 'Esponjas', 3, 'Manto ondulado de color rosado a púrpura pálido, con el borde plisado característico del género Felimida.'),
('rostangaroja', 'molusco', 'Nudibranchia', 'Rostanga roja', 'Rostanga rubra', 'Canarias', ARRAY['canarias'], 'MOL-09', '20 mm', 'Rocas cubiertas de esponjas rojas', '0–30 m', 'Muy lenta', 'Esponjas rojas como Ophlitaspongia seriata', 3, 'De un rojo anaranjado intenso que le sirve de camuflaje perfecto sobre las esponjas rojas incrustantes de las que se alimenta y en las que pone sus huevos.'),
('gargamella', 'molusco', 'Nudibranchia', 'Gargamella', 'Gargamella perezi', 'Canarias', ARRAY['canarias'], 'MOL-10', '30 mm', 'Fondos rocosos', '0–40 m', 'Muy lenta', 'Esponjas', 4, 'Dorido de cuerpo tuberculado y colores apagados, poco frecuente, que pasa desapercibido sobre el fondo rocoso donde se alimenta de esponjas.'),
('taringa', 'molusco', 'Nudibranchia', 'Taringa', 'Taringa ascitica', 'Canarias', ARRAY['canarias'], 'MOL-11', '30 mm', 'Fondos rocosos', '0–40 m', 'Muy lenta', 'Esponjas', 4, 'Dorido de superficie granulosa y coloración críptica, propio de fondos rocosos donde se confunde fácilmente con el sustrato.'),
('dendrodoris', 'molusco', 'Nudibranchia', 'Dendrodoris', 'Dendrodoris grandiflora', 'Canarias', ARRAY['canarias'], 'MOL-12', '80 mm', 'Fondos rocosos y de coralígeno', '0–50 m', 'Muy lenta', 'Esponjas', 3, 'Uno de los nudibranquios de mayor tamaño del catálogo, de cuerpo blando y sin branquias visibles a simple vista; respira a través de toda la piel.'),
('marionia', 'molusco', 'Nudibranchia', 'Marionia', 'Marionia blainvillea', 'Canarias', ARRAY['canarias'], 'MOL-13', '60 mm', 'Fondos rocosos y de coralígeno', '0–50 m', 'Muy lenta', 'Gorgonias y otros octocorales', 3, 'Cuerpo alargado cubierto de papilas ramificadas, camuflado entre las gorgonias y corales blandos de los que se alimenta.'),
('hancockia', 'molusco', 'Nudibranchia', 'Hancockia', 'Hancockia uncinata', 'Canarias', ARRAY['canarias'], 'MOL-14', '20 mm', 'Fondos rocosos con hidrozoos', '0–30 m', 'Muy lenta', 'Hidrozoos como Clytia hemisphaerica', 4, 'Pequeño y poco frecuente, con papilas ramificadas en forma de abanico. Extrae los nematocistos urticantes de los hidrozoos de los que se alimenta para su propia defensa.'),
('scyllaea', 'molusco', 'Nudibranchia', 'Nudibranquio del sargazo', 'Scyllaea pelagica', 'Canarias', ARRAY['canarias'], 'MOL-15', '50 mm', 'Sargazo flotante', '0–5 m', 'Muy lenta', 'Hidrozoos que crecen sobre el sargazo', 4, 'Especie pelágica que vive sobre masas de sargazo a la deriva, con cerata en forma de aletas que imitan perfectamente las hojas del alga.'),
('doto', 'molusco', 'Nudibranchia', 'Doto', 'Doto escatllari', 'Canarias', ARRAY['canarias'], 'MOL-16', '10 mm', 'Fondos rocosos con hidrozoos', '0–30 m', 'Muy lenta', 'Hidrozoos de la familia Sertulariidae', 4, 'Especie descrita en Canarias, diminuta y de cuerpo translúcido con cerata tuberculadas donde se transparenta la glándula digestiva.'),
('flabellinaafinis', 'molusco', 'Nudibranchia', 'Flabellina violeta', 'Flabellina affinis', 'Canarias', ARRAY['canarias'], 'MOL-17', '30 mm', 'Fondos rocosos con hidrozoos', '0–40 m', 'Muy lenta', 'Hidrozoos', 3, 'De un violeta intenso uniforme, con cerata alargadas dispuestas en penachos a lo largo del dorso. Uno de los eólidos más reconocibles del Atlántico oriental.'),
('dicata', 'molusco', 'Nudibranchia', 'Dicata', 'Dicata odhneri', 'Canarias', ARRAY['canarias'], 'MOL-18', '10 mm', 'Fondos rocosos', '0–30 m', 'Muy lenta', 'Desconocida, probablemente hidrozoos', 4, 'Pequeño eólido blanco translúcido con las puntas de rinóforos y tentáculos orales amarillas. Muy raro de encontrar; se desconocen bien sus hábitos.'),
('limenandra', 'molusco', 'Nudibranchia', 'Limenandra', 'Limenandra nodosa', 'Canarias', ARRAY['canarias'], 'MOL-19', '20 mm', 'Fondos rocosos', '0–30 m', 'Muy lenta', 'Anémonas e hidrozoos', 4, 'Eólido de cerata cortas y nudosas dispuestas en grupos compactos, típico de la familia Aeolidiidae, depredadora de cnidarios urticantes.'),
('trinchesia', 'molusco', 'Nudibranchia', 'Trinchesia de Génova', 'Trinchesia genovae', 'Canarias', ARRAY['canarias'], 'MOL-20', '6 mm', 'Fondos rocosos con hidrozoos', '0–30 m', 'Muy lenta', 'Hidrozoos', 4, 'Uno de los nudibranquios más diminutos del catálogo, de apenas medio centímetro. Descrito en Génova, se alimenta de pequeñas colonias de hidrozoos.'),
('glaucus', 'molusco', 'Nudibranchia', 'Dragón azul', 'Glaucus atlanticus', 'Canarias', ARRAY['canarias'], 'MOL-21', '30 mm', 'Superficie del océano abierto', '0–1 m', 'Muy lenta', 'Carabela portuguesa (Physalia physalis) y otros sifonóforos', 5, 'Flota bocabajo en la superficie gracias a una burbuja de aire que traga, dejándose llevar por el viento y las corrientes. Almacena los nematocistos urticantes de sus presas para su propia defensa, por lo que su picadura puede ser más dolorosa que la de la propia carabela.'),
('juriellimon', 'pez', 'Carangiformes', 'Juriel limón', 'Pseudocaranx dentex', 'Canarias', ARRAY['canarias','mediterraneo'], 'PEZ-78', '0.6 m', 'Fondos rocosos y arenosos costeros, y aguas abiertas', '0–80 m', 'Rápida', 'Peces pequeños, crustáceos e invertebrados del fondo', 2, 'Carángido plateado con una banda amarilla longitudinal y una mancha oscura sobre el opérculo. Forma bancos que patrullan veriles y bajones, y hociquea el fondo arenoso en busca de invertebrados.'),
('tamborilazul', 'pez', 'Tetraodontiformes', 'Tamboril azul', 'Sphoeroides pachygaster', 'Canarias', ARRAY['canarias','mediterraneo'], 'PEZ-79', '0.4 m', 'Fondos de arena y roca, más profundos que sus parientes', '20–200 m', 'Lenta', 'Crustáceos, moluscos y cefalópodos', 3, 'Se distingue del resto de tamboriles por su piel completamente lisa, sin espinas ni manchas marcadas, y su tono gris azulado con el vientre blanco. Como todos los tetraodóntidos, acumula tetrodotoxina y no es comestible.')
